def finding_for(case):
    values = {
        "id": case["id"], "tool": case.get("tool", ""),
        "rule_id": case.get("rule_id", ""), "title": case.get("title", ""),
        "description": case.get("description", ""), "file": case.get("file", ""),
        "line_start": case.get("line_start", 1), "line_end": case.get("line_end", 1),
        "severity": case.get("severity", "high"), "cwe": case.get("cwe"),
        "owasp": case.get("owasp"), "corroborating_tools": case.get("corroborating_tools", []),
        "raw_outputs": case.get("raw_outputs", {}), "snippet": case.get("snippet", ""),
    }
    return SimpleNamespace(**values)
